mapper.select:
SELECT id, user_id, session_id, memory_type, memory_key, content, keywords,
       source_role, confidence, hit_count, created_at, updated_at
FROM long_term_memory
WHERE user_id = #{userId}
  AND memory_type = #{memoryType}
  AND memory_key = #{memoryKey}
LIMIT 1

mapper.insert:
INSERT INTO long_term_memory (
    user_id, session_id, memory_type, memory_key, content, keywords, source_role, confidence, hit_count
) VALUES (
    #{userId}, #{sessionId}, #{memoryType}, #{memoryKey}, #{content}, #{keywords}, #{sourceRole}, #{confidence}, #{hitCount}
)

mapper.select:
SELECT id, user_id, session_id, memory_type, memory_key, content, keywords,
       source_role, confidence, hit_count, created_at, updated_at
FROM long_term_memory
WHERE user_id = #{userId}
ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
